<?php $pageTitle = 'Labour Attendance'; ?>
<div class="d-flex flex-wrap justify-content-between align-items-center mb-4 gap-2"><div><h2 class="h4 mb-1">Daily Labour Attendance</h2><p class="text-muted mb-0">Record hours, status, overtime, and daily labour cost.</p></div><div class="d-flex gap-2"><a class="btn btn-outline-secondary" href="<?= e(app_url('/labour/export/attendance/csv')) ?>">CSV</a><a class="btn btn-outline-secondary" href="<?= e(app_url('/labour/export/attendance/excel')) ?>">Excel</a><a class="btn btn-outline-secondary" href="<?= e(app_url('/labour/export/attendance/pdf')) ?>">PDF</a></div></div>
<div class="card border-0 shadow-sm mb-4"><div class="card-body"><form class="row g-2" method="get"><div class="col-md-2"><label class="form-label">Date</label><input type="date" name="date" value="<?= e($filters['date']) ?>" class="form-control"></div><div class="col-md-2"><label class="form-label">Project ID</label><input type="number" name="project_id" value="<?= e((string)$filters['project_id']) ?>" class="form-control"></div><div class="col-md-2"><label class="form-label">Contractor ID</label><input type="number" name="contractor_id" value="<?= e((string)$filters['contractor_id']) ?>" class="form-control"></div><div class="col-md-2"><label class="form-label">Trade</label><input name="trade" value="<?= e($filters['trade']) ?>" class="form-control"></div><div class="col-md-2"><label class="form-label">Status</label><select name="attendance_status" class="form-select"><option value="">All</option><?php foreach (['Present','Absent','Half Day','Leave'] as $status): ?><option <?= $filters['attendance_status'] === $status ? 'selected' : '' ?>><?= e($status) ?></option><?php endforeach; ?></select></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Filter</button></div></form></div></div>
<div class="card border-0 shadow-sm mb-4"><div class="card-body"><h3 class="h6 mb-3">Add Attendance</h3><form method="post" action="<?= e(app_url('/labour/attendance')) ?>"><input type="hidden" name="<?= e((string)env('CSRF_TOKEN_NAME', 'csrf_token')) ?>" value="<?= e(csrf_token()) ?>"><div class="row g-3"><div class="col-md-2"><label class="form-label">Date</label><input type="date" name="date" value="<?= e(date('Y-m-d')) ?>" class="form-control" required></div><div class="col-md-3"><label class="form-label">Labour</label><select name="labour_id" class="form-select" required><option value="">Select labour</option><?php foreach ($labours as $labour): ?><option value="<?= e($labour['id']) ?>"><?= e($labour['labour_id'] . ' - ' . $labour['name'] . ' (' . $labour['trade'] . ')') ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label class="form-label">Project ID</label><select name="project_id" class="form-select"><option value="">Select project</option><?php foreach ($projects as $project): ?><option value="<?= e($project['id']) ?>"><?= e($project['id'] . ' - ' . $project['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label class="form-label">Contractor</label><select name="contractor_id" class="form-select"><option value="">Select contractor</option><?php foreach ($contractors as $contractor): ?><option value="<?= e($contractor['id']) ?>"><?= e($contractor['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Site</label><input name="site" class="form-control"></div><div class="col-md-2"><label class="form-label">Trade</label><input name="trade" class="form-control"></div><div class="col-md-2"><label class="form-label">In Time</label><input type="time" name="check_in" class="form-control"></div><div class="col-md-2"><label class="form-label">Out Time</label><input type="time" name="check_out" class="form-control"></div><div class="col-md-2"><label class="form-label">Status</label><select name="attendance_status" class="form-select" required><?php foreach (['Present','Absent','Half Day','Leave'] as $status): ?><option><?= e($status) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Remarks</label><input name="remarks" class="form-control"></div></div><button class="btn btn-accent mt-3">Save Attendance</button></form></div></div>
<div class="card border-0 shadow-sm"><div class="card-body"><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Date</th><th>Labour</th><th>Project</th><th>Contractor</th><th>Hours</th><th>OT</th><th>Status</th><th>Wage</th><th></th></tr></thead><tbody><?php foreach ($records as $record): ?><tr><td><?= e(format_date($record['date'])) ?></td><td><?= e($record['labour_code'] . ' - ' . $record['labour_name']) ?><div class="small text-muted"><?= e($record['trade'] ?? '') ?></div></td><td><?= e($record['project_name'] ?? '-') ?></td><td><?= e($record['contractor_name'] ?? '-') ?></td><td><?= e($record['working_hours']) ?></td><td><?= e($record['overtime_hours']) ?></td><td><span class="badge text-bg-secondary"><?= e($record['attendance_status']) ?></span></td><td><?= e(format_currency($record['daily_wage'])) ?></td><td><form method="post" action="<?= e(app_url('/labour/attendance/' . $record['id'] . '/delete')) ?>" onsubmit="return confirm('Delete this attendance record?')"><input type="hidden" name="<?= e((string)env('CSRF_TOKEN_NAME', 'csrf_token')) ?>" value="<?= e(csrf_token()) ?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div>
